insert into public.cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('m-collection-s740','milestone','S740''s collection: 80 records','S740 (2026-11-26, the routine''s 13:12Z run): 80 records collected (30 passing by reread or load; 50 named gaps by guarded plans), plus Copper Mountain''s registry row moved to the reissue. Display 9e28519af71f (#3886); land #3892. Census before the land: 15,610 of 20,282 pass, 4,082 without, 590 with a named gap. Paid reads about $1.10.',array['program-requirements','collection','milestone'],'proposed','#3886; docs/session_741_handoff.md',null,null,'SkySkimmer (S740)','2026-11-26'),
('f-units-within-range-by-key-only-s740','fact','The units within-range kind files only by reviewed key lists','S740: the kind units_within_printed_range (50) in kb/_program_named_gaps.py is filed only by reviewed key lists. Its self-recall: on 28 held answers the figures alone were right on 6 and wrong on 22, so no matcher may file it. Past the listed keys it files nothing over 12,141 passing records and 48,486 held readings. Six held records were filed by key.',array['program-requirements','named-gaps','units','recall'],'proposed','docs/session_741_handoff.md',null,null,'SkySkimmer (S740)','2026-11-26'),
('d-waived-course-counted-at-range-top-s740','decision','A waived course counted keeps its gap when the sum sits at the top of the printed range','S740 conductor: San Bernardino Valley 22771 and 22776 sum at the top of their printed ranges (24 in 20-24, 44 in 40-44). waived_course_counted stands for both: the gap names the record''s own reading fault (it counted the 0-4 unit course the page lets a student waive), which S739''s within-range rule, for a record with nothing wrong, does not cover.',array['program-requirements','named-gaps','san-bernardino-valley','conductor'],'proposed','docs/session_741_handoff.md',null,null,'SkySkimmer (S740)','2026-11-26'),
('d-copper-mountain-registry-moves-to-reissue-s740','decision','Copper Mountain''s registry row moves to the reissued catalog','S740 conductor: plan s740r1 moved Copper Mountain''s registry row (Sam''s Sheet 88 correction, applied by S405) to the same 2026-2027 catalog''s reissue (Final-26-27-Catalog-11.18.26r1.pdf), the old address answering 404. One row, guarded; the history trigger and the receipt hold the before-row. New source evidence reopens a person''s save.',array['program-requirements','registry','copper-mountain','conductor'],'proposed','docs/session_741_handoff.md',null,null,'SkySkimmer (S740)','2026-11-26'),
('p-reread-posts-raw-reconcile-keep-better-first-s740','pitfall','A reread posts the raw reconcile unless keep-better runs first','S740: a reread posts the raw reconcile, so Solano lost three overall passes (20973, 36420, 42205) on ligature text until kb/_program_reread_keep_better.py restored them from main. Run keep-better first, against a live read of the college''s checked rows, before every reread; San Bernardino Valley''s five noncredit and 17829 needed it too.',array['program-requirements','reread','keep-better','pitfall'],'proposed','docs/session_741_handoff.md',null,null,'SkySkimmer (S740)','2026-11-26'),
('p-staged-read-predating-page-counts-held-by-price-step-s740','pitfall','A staged read from a capture that predates page counts extracts nothing','S740: a staged read (sources_from an earlier artifact) whose capture predates the page counts ends green and extracts nothing, because the price step holds it with no charge (run 45836017170, San Diego City 22367). A long fresh capture is needed. A free staged run priced at $0.10 does work when the capture carries the counts.',array['program-requirements','reads','price-step','pitfall'],'proposed','docs/session_741_handoff.md',null,null,'SkySkimmer (S740)','2026-11-26'),
('p-free-reconcile-cannot-reach-moved-address-records-s740','pitfall','A free reconcile cannot reach records read from an address the registry moved','S740: after the registry moves a college''s catalog address, the moved-page guard leaves records read from the old address as filed, so a free reconcile moves nothing. A paid read of the reissue does it: Copper Mountain''s eight held programs, about $0.75, read 45855512160, reread 45855997214; 18519 passes.',array['program-requirements','reconcile','moved-page-guard','pitfall'],'proposed','docs/session_741_handoff.md',null,null,'SkySkimmer (S740)','2026-11-26'),
('f-rule-b-refuses-san-diego-city-22367-s740','fact','Rule B of the reader''s page checks refuses San Diego City 22367','S740: rule B reads 22367''s entry as descriptions, because its own Courses child page prints four course descriptions. The 90-minute read 45836824944 refused at the price step (only= refused: 22367 has no text in the capture). It needs a reader change with a self-recall and a second reader, then one more capture. CPL_READER_PAGE_CHECKS=0 would switch the rules off statewide; no switch.',array['program-requirements','reader','san-diego-city','follow-up'],'proposed','docs/session_741_handoff.md',null,null,'SkySkimmer (S740)','2026-11-26'),
('p-sandbox-python-311-check-generated-false-stale-s740','pitfall','The sandbox''s default python3 is 3.11 and check_generated.sh prints false STALE lines','S740: under Python 3.11, scripts/check_generated.sh prints false STALE lines for the generated files. Build with 3.12: a shim at /home/user/wt/.py312bin put first on PATH ran every worker''s generators and the display build 9e28519af71f. Read the last line of check_generated.sh only after the shim is on PATH.',array['ci','generated-files','python','pitfall'],'proposed','docs/session_741_handoff.md',null,null,'SkySkimmer (S740)','2026-11-26'),
('p-harness-pins-worker-worktree-s740','pitfall','The harness pins each worker to its own agent worktree, and worker times run ahead','S740: the harness pins each worker to its own .claude/worktrees/agent-* worktree whatever path the brief names, so a brief''s /home/user/wt/<name> is a sibling clone the worker may not use. Worker report times also ran a few minutes ahead of the conductor''s clock; order a log by the conductor''s reading, not the worker''s stamp.',array['conductor','workers','harness','pitfall'],'proposed','docs/session_741_handoff.md',null,null,'SkySkimmer (S740)','2026-11-26')
on conflict (slug) do nothing;

insert into public.cpl_memory_log (memory_id, actor, action, note, after)
