from public.cpl_memory m where m.slug in ('m-collection-s740','f-units-within-range-by-key-only-s740','d-waived-course-counted-at-range-top-s740','d-copper-mountain-registry-moves-to-reissue-s740','p-reread-posts-raw-reconcile-keep-better-first-s740','p-staged-read-predating-page-counts-held-by-price-step-s740','p-free-reconcile-cannot-reach-moved-address-records-s740','f-rule-b-refuses-san-diego-city-22367-s740','p-sandbox-python-311-check-generated-false-stale-s740','p-harness-pins-worker-worktree-s740')
  and m.author = 'SkySkimmer (S740)'
  and not exists (select 1 from public.cpl_memory_log l where l.memory_id = m.id and l.action = 'create');

select slug, kind, status, length(summary) as summary_len from public.cpl_memory
where slug in ('m-collection-s740','f-units-within-range-by-key-only-s740','d-waived-course-counted-at-range-top-s740','d-copper-mountain-registry-moves-to-reissue-s740','p-reread-posts-raw-reconcile-keep-better-first-s740','p-staged-read-predating-page-counts-held-by-price-step-s740','p-free-reconcile-cannot-reach-moved-address-records-s740','f-rule-b-refuses-san-diego-city-22367-s740','p-sandbox-python-311-check-generated-false-stale-s740','p-harness-pins-worker-worktree-s740')
  and author = 'SkySkimmer (S740)'
